-- Preserve CMS fixtures privately; new articles require an explicit publication decision.
ALTER TABLE public.market_articles ADD COLUMN is_published boolean NOT NULL DEFAULT true;
UPDATE public.market_articles SET is_published=false WHERE focus_asset='btc' AND
 ((slug='tsest' AND title='Tsest' AND content='test123') OR
 (slug='test2' AND title='test2' AND content='Hello, this is a test project ran by the developer team of tradehq. If you receive this message, thank you for signing up to our newsletter, we will send out our best trading advice to you once every week or so.'));
ALTER TABLE public.market_articles ALTER COLUMN is_published SET DEFAULT false;
ALTER POLICY "Articles are publicly readable" ON public.market_articles USING(is_published);

CREATE TABLE public.daily_practice_drafts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), effective_from date NOT NULL,
 revision integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','rejected')),
 document jsonb NOT NULL, research jsonb NOT NULL DEFAULT '{}'::jsonb,
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CHECK(octet_length(document::text)<=400000)
);
CREATE TABLE public.daily_practice_batches (
 id uuid PRIMARY KEY REFERENCES public.daily_practice_drafts(id), effective_from date NOT NULL,
 document jsonb NOT NULL, revision integer NOT NULL, reviewed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.daily_practice_drafts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.daily_practice_batches ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.daily_practice_drafts,public.daily_practice_batches FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.daily_practice_drafts,public.daily_practice_batches TO service_role;
GRANT SELECT ON public.daily_practice_batches TO anon,authenticated;
CREATE POLICY "Approved effective practice banks" ON public.daily_practice_batches FOR SELECT TO anon,authenticated
 USING(effective_from <= (clock_timestamp() AT TIME ZONE 'Asia/Colombo')::date);
CREATE FUNCTION public.get_daily_practice_bank() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT document FROM public.daily_practice_batches ORDER BY effective_from DESC,reviewed_at DESC LIMIT 1;
$$;
REVOKE ALL ON FUNCTION public.get_daily_practice_bank() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_daily_practice_bank() TO anon,authenticated,service_role;

CREATE TABLE tradehq_private.daily_practice_state (
 id boolean PRIMARY KEY DEFAULT true CHECK(id), enabled boolean NOT NULL DEFAULT true,
 next_due date NOT NULL DEFAULT DATE '2026-12-09', exercises jsonb NOT NULL DEFAULT '[]'::jsonb,
 attempts integer NOT NULL DEFAULT 0, retry_after timestamptz, last_error text,
 pending_hash text, pending_expires timestamptz, lease uuid, lease_expires timestamptz,
 last_started timestamptz, last_finished timestamptz, CHECK(jsonb_array_length(exercises)<=50)
);
INSERT INTO tradehq_private.daily_practice_state(id) VALUES(true);
ALTER TABLE tradehq_private.daily_practice_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON tradehq_private.daily_practice_state FROM PUBLIC,anon,authenticated;
GRANT ALL ON tradehq_private.daily_practice_state TO service_role;

CREATE FUNCTION tradehq_private.daily_exercises_valid(items jsonb, expected integer DEFAULT 50) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE e jsonb; q jsonb; bar jsonb; src jsonb; field text; ids text[]:='{}'; titles text[]:='{}'; prompts text[]:='{}'; val text;
BEGIN
 IF jsonb_typeof(items) IS DISTINCT FROM 'array' OR jsonb_array_length(items)<>expected OR expected NOT IN (10,50) THEN RETURN false; END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(items) LOOP
  IF jsonb_typeof(e) IS DISTINCT FROM 'object' OR coalesce(e->>'id','') !~ '^[a-z0-9-]{1,90}$' OR e->>'id'=ANY(ids)
  OR length(trim(coalesce(e->>'title',''))) NOT BETWEEN 8 AND 120
  OR lower(e->>'title')=ANY(titles) OR e->>'category' NOT IN ('Portfolio arithmetic','Costs and orders','Price data','Risk and uncertainty','Decision habits')
  OR length(trim(coalesce(e->>'scenario',''))) NOT BETWEEN 180 AND 3000
  OR length(trim(coalesce(e->>'reflection',''))) NOT BETWEEN 20 AND 500
  OR length(trim(coalesce(e->>'reflectionGuide',''))) NOT BETWEEN 120 AND 1800 THEN RETURN false; END IF;
  FOREACH field IN ARRAY ARRAY['id','title','category','scenario','reflection','reflectionGuide'] LOOP
   IF jsonb_typeof(e->field) IS DISTINCT FROM 'string' THEN RETURN false; END IF;
  END LOOP;
  ids:=array_append(ids,e->>'id'); titles:=array_append(titles,lower(e->>'title'));
  IF jsonb_typeof(e->'visual') IS DISTINCT FROM 'object' OR length(trim(coalesce(e#>>'{visual,caption}',''))) NOT BETWEEN 10 AND 240
  OR length(trim(coalesce(e#>>'{visual,unit}',''))) NOT BETWEEN 1 AND 30
  OR jsonb_typeof(e#>'{visual,bars}') IS DISTINCT FROM 'array' OR jsonb_array_length(e#>'{visual,bars}') NOT BETWEEN 2 AND 6 THEN RETURN false; END IF;
  FOR bar IN SELECT value FROM jsonb_array_elements(e#>'{visual,bars}') LOOP
   IF jsonb_typeof(bar->'label') IS DISTINCT FROM 'string' OR length(trim(bar->>'label')) NOT BETWEEN 1 AND 50
   OR jsonb_typeof(bar->'value') IS DISTINCT FROM 'number' OR (bar->>'value')::numeric NOT BETWEEN 0 AND 1000000000 THEN RETURN false; END IF;
  END LOOP;
  IF jsonb_typeof(e->'questions') IS DISTINCT FROM 'array' OR jsonb_array_length(e->'questions')<>3 THEN RETURN false; END IF;
  FOR q IN SELECT value FROM jsonb_array_elements(e->'questions') LOOP
   IF jsonb_typeof(q->'prompt') IS DISTINCT FROM 'string' OR length(trim(q->>'prompt')) NOT BETWEEN 12 AND 450
   OR jsonb_typeof(q->'explanation') IS DISTINCT FROM 'string' OR length(trim(q->>'explanation')) NOT BETWEEN 100 AND 2000
   OR jsonb_typeof(q->'options') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'options')<>3
   OR jsonb_typeof(q->'correctAnswer') IS DISTINCT FROM 'number' OR coalesce(q->>'correctAnswer','') !~ '^[0-2]$' THEN RETURN false; END IF;
   FOR val IN SELECT value FROM jsonb_array_elements_text(q->'options') LOOP
    IF length(trim(val)) NOT BETWEEN 1 AND 350 THEN RETURN false; END IF;
   END LOOP;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(q->'options') v WHERE jsonb_typeof(v) IS DISTINCT FROM 'string')
   OR (SELECT count(DISTINCT lower(trim(value))) FROM jsonb_array_elements_text(q->'options'))<>3 THEN RETURN false; END IF;
   val:=lower(regexp_replace(q->>'prompt','[^a-zA-Z0-9]+',' ','g'));
   IF val=ANY(prompts) THEN RETURN false; END IF; prompts:=array_append(prompts,val);
  END LOOP;
  IF jsonb_typeof(e->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(e->'sources') NOT BETWEEN 1 AND 4 THEN RETURN false; END IF;
  FOR src IN SELECT value FROM jsonb_array_elements(e->'sources') LOOP
   IF jsonb_typeof(src->'label') IS DISTINCT FROM 'string' OR length(trim(src->>'label')) NOT BETWEEN 3 AND 160
   OR jsonb_typeof(src->'url') IS DISTINCT FROM 'string'
   OR coalesce(src->>'url','') !~ '^https://(www[.]investor[.]gov|www[.]finra[.]org|www[.]cftc[.]gov|www[.]federalreserve[.]gov|docs[.]coingecko[.]com|www[.]coingecko[.]com)/[^[:space:]<>]*$' THEN RETURN false; END IF;
  END LOOP;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END; $$;

CREATE FUNCTION tradehq_private.daily_practice_status() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('enabled',s.enabled,'nextDue',s.next_due,'prepareAfter',s.next_due-7,
 'completed',jsonb_array_length(s.exercises),'attempts',s.attempts,'retryAfter',s.retry_after,
 'lastError',s.last_error,'lastStarted',s.last_started,'lastFinished',s.last_finished,
 'model',c.model,'freeConfirmed',c.free_confirmed,
 'hasApiKey',EXISTS(SELECT 1 FROM vault.secrets WHERE name='tradehq_course_gemini_key'))
 FROM tradehq_private.daily_practice_state s JOIN tradehq_private.course_generation_settings c USING(id);
$$;
CREATE FUNCTION tradehq_private.configure_daily_practice(p_enabled boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_enabled IS NULL THEN RAISE EXCEPTION 'Daily settings are invalid'; END IF;
 UPDATE tradehq_private.daily_practice_state SET enabled=p_enabled WHERE id;
 RETURN tradehq_private.daily_practice_status();
END; $$;
CREATE FUNCTION tradehq_private.save_daily_practice(p_id uuid,p_revision integer,p_document jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE row public.daily_practice_drafts;
BEGIN
 IF NOT tradehq_private.daily_exercises_valid(p_document->'exercises') OR octet_length(p_document::text)>400000
 OR coalesce(p_document->>'effectiveFrom','') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Daily bank is incomplete'; END IF;
 UPDATE public.daily_practice_drafts SET document=p_document-'reviewer'-'reviewedAt',effective_from=(p_document->>'effectiveFrom')::date,
 revision=revision+1,status='draft',updated_at=clock_timestamp() WHERE id=p_id AND revision=p_revision RETURNING * INTO row;
 IF NOT FOUND THEN RAISE EXCEPTION 'Daily bank changed; reload before saving'; END IF;
 RETURN to_jsonb(row);
END; $$;
CREATE FUNCTION tradehq_private.publish_daily_practice(p_id uuid,p_revision integer,p_reviewer text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE row public.daily_practice_drafts; doc jsonb;
BEGIN
 SELECT * INTO row FROM public.daily_practice_drafts WHERE id=p_id AND revision=p_revision FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Daily bank changed; reload before approving'; END IF;
 IF row.status='rejected' OR NOT tradehq_private.daily_exercises_valid(row.document->'exercises')
 OR length(trim(coalesce(p_reviewer,''))) NOT BETWEEN 2 AND 80 THEN RAISE EXCEPTION 'Daily bank is incomplete'; END IF;
 doc:=row.document||jsonb_build_object('id',row.id::text,'effectiveFrom',row.effective_from::text,'reviewer',trim(p_reviewer),'reviewedAt',clock_timestamp());
 INSERT INTO public.daily_practice_batches(id,effective_from,document,revision) VALUES(row.id,row.effective_from,doc,row.revision)
 ON CONFLICT(id) DO UPDATE SET effective_from=excluded.effective_from,document=excluded.document,revision=excluded.revision,reviewed_at=clock_timestamp();
 UPDATE public.daily_practice_drafts SET status='published',updated_at=clock_timestamp() WHERE id=row.id RETURNING * INTO row;
 RETURN to_jsonb(row);
END; $$;
CREATE FUNCTION tradehq_private.reject_daily_practice(p_id uuid,p_revision integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE row public.daily_practice_drafts;
BEGIN
 UPDATE public.daily_practice_drafts SET status='rejected',revision=revision+1,updated_at=clock_timestamp()
 WHERE id=p_id AND revision=p_revision RETURNING * INTO row;
 IF NOT FOUND THEN RAISE EXCEPTION 'Daily bank changed; reload before rejecting'; END IF;
 -- Existing approved snapshots remain available; rejection applies to the private draft.
 RETURN to_jsonb(row);
END; $$;

CREATE FUNCTION tradehq_private.request_daily_practice(p_manual boolean DEFAULT false) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s tradehq_private.daily_practice_state; c tradehq_private.course_generation_settings; token text; request_id bigint;
BEGIN
 SELECT * INTO c FROM tradehq_private.course_generation_settings WHERE id;
 SELECT * INTO s FROM tradehq_private.daily_practice_state WHERE id FOR UPDATE;
 IF NOT s.enabled OR NOT c.free_confirmed OR NOT EXISTS(SELECT 1 FROM vault.secrets WHERE name='tradehq_course_gemini_key')
 OR (NOT p_manual AND (clock_timestamp() AT TIME ZONE 'Asia/Colombo')::date<s.next_due-7)
 OR s.attempts>=3 OR s.retry_after>clock_timestamp() OR s.pending_expires>clock_timestamp() OR s.lease_expires>clock_timestamp()
 OR s.last_started>clock_timestamp()-interval '2 minutes' THEN RETURN NULL; END IF;
 token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
 UPDATE tradehq_private.daily_practice_state SET pending_hash=encode(sha256(convert_to(token,'UTF8')),'hex'),
 pending_expires=clock_timestamp()+interval '2 minutes' WHERE id;
 SELECT net.http_post(url:='https://cbdktpjgczhthflspqjb.supabase.co/functions/v1/generate-daily-practice',body:='{}'::jsonb,
 headers:=jsonb_build_object('Content-Type','application/json','x-generation-token',token),timeout_milliseconds:=120000) INTO request_id;
 RETURN request_id;
END; $$;
CREATE FUNCTION tradehq_private.claim_daily_practice(p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s tradehq_private.daily_practice_state; c tradehq_private.course_generation_settings; key text;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[a-f0-9]{64}$' THEN RETURN NULL; END IF;
 SELECT * INTO c FROM tradehq_private.course_generation_settings WHERE id;
 IF NOT c.free_confirmed THEN RETURN NULL; END IF;
 UPDATE tradehq_private.daily_practice_state SET pending_hash=NULL,pending_expires=NULL,lease=gen_random_uuid(),
 lease_expires=clock_timestamp()+interval '5 minutes',last_started=clock_timestamp(),attempts=attempts+1
 WHERE id AND enabled AND pending_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') AND pending_expires>clock_timestamp()
 AND (lease_expires IS NULL OR lease_expires<=clock_timestamp()) AND attempts<3 AND (retry_after IS NULL OR retry_after<=clock_timestamp())
 RETURNING * INTO s;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT decrypted_secret INTO key FROM vault.decrypted_secrets WHERE name='tradehq_course_gemini_key';
 RETURN jsonb_build_object('lease',s.lease,'effectiveFrom',s.next_due,'apiKey',key,'model',c.model,'exercises',s.exercises,
 'existing',coalesce((SELECT jsonb_agg(jsonb_build_object('title',e->>'title','scenario',e->>'scenario','questions',e->'questions'))
 FROM (SELECT document FROM public.daily_practice_drafts ORDER BY effective_from DESC LIMIT 6) d CROSS JOIN LATERAL jsonb_array_elements(d.document->'exercises') e),'[]'::jsonb));
END; $$;
CREATE FUNCTION tradehq_private.finish_daily_practice(p_lease uuid,p_exercises jsonb,p_research jsonb,p_error text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s tradehq_private.daily_practice_state; items jsonb; draft uuid;
BEGIN
 SELECT * INTO s FROM tradehq_private.daily_practice_state WHERE id AND lease=p_lease AND lease_expires>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF p_error IS NULL THEN
  IF NOT tradehq_private.daily_exercises_valid(p_exercises,10) THEN RAISE EXCEPTION 'Daily bank is incomplete'; END IF;
  items:=s.exercises||p_exercises;
  IF (SELECT count(DISTINCT lower(value->>'title')) FROM jsonb_array_elements(items))<>jsonb_array_length(items)
  OR (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(items))<>jsonb_array_length(items)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_exercises) n,public.daily_practice_drafts d,
    LATERAL jsonb_array_elements(d.document->'exercises') old WHERE lower(n->>'title')=lower(old->>'title')) THEN RAISE EXCEPTION 'Daily bank repeats existing content'; END IF;
  IF jsonb_array_length(items)=50 THEN
   IF NOT tradehq_private.daily_exercises_valid(items) THEN RAISE EXCEPTION 'Daily bank is incomplete'; END IF;
   draft:=gen_random_uuid();
   INSERT INTO public.daily_practice_drafts(id,effective_from,document,research) VALUES(draft,s.next_due,
   jsonb_build_object('id',draft::text,'effectiveFrom',s.next_due,'exercises',items),
   coalesce(p_research,'{}'::jsonb)||jsonb_build_object('aiAssisted',true,'approvalRequired',true));
   UPDATE tradehq_private.daily_practice_state SET next_due=(next_due+interval '2 months')::date,exercises='[]',attempts=0,last_error=NULL,retry_after=NULL WHERE id;
  ELSE
   UPDATE tradehq_private.daily_practice_state SET exercises=items,attempts=0,last_error=NULL,retry_after=NULL WHERE id;
  END IF;
 ELSE
  UPDATE tradehq_private.daily_practice_state SET last_error=left(p_error,1000),retry_after=clock_timestamp()+interval '1 day' WHERE id;
 END IF;
 UPDATE tradehq_private.daily_practice_state SET lease=NULL,lease_expires=NULL,last_finished=clock_timestamp() WHERE id;
 RETURN true;
END; $$;

